cpp_source = """
#include <hip/hip_runtime.h>

__device__ inline float silu(float x) {
    return x / (1.0f + expf(-x));
}

__global__ void silu_mul_kernel(const float* __restrict__ input, float* __restrict__ output, int rows, int cols) {
    // Input shape: (rows, 2 * cols)
    // input contains [gate, up] concatenated along the last dimension
    // Output shape: (rows, cols)
    // output = silu(gate) * up

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = rows * cols;

    if (idx < total_elements) {
        int row = idx / cols;
        int col = idx % cols;

        // The input has stride 2*cols
        // gate is at [0, cols-1], up is at [cols, 2*cols-1]
        int gate_idx = row * (2 * cols) + col;
        int up_idx = gate_idx + cols;

        float gate_val = input[gate_idx];
        float up_val = input[up_idx];

        output[idx] = silu(gate_val) * up_val;
    }
}

torch::Tensor silu_mul_hip(torch::Tensor input) {
    // Input tensor shape: (rows, 2*cols)
    // We infer cols from the last dimension
    auto rows = input.size(0);
    auto double_cols = input.size(1);

    // Ensure dimension is even
    if (double_cols % 2 != 0) {
        // Should not happen in this specific architecture
        return torch::zeros({rows, double_cols/2}, input.options()); 
    }

    auto cols = double_cols / 2;
    auto output = torch::empty({rows, cols}, input.options());

    int total_elements = rows * cols;
    const int block_size = 256;
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    silu_mul_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        rows,
        cols
    );

    return output;
}
"""

module = load_inline(
    name="moe_kernels_v1",
    cpp_sources=cpp_source,
    functions=["silu_mul_hip"],
    verbose=False,
    extra_cflags=['-O3']
)

class ModelNew(nn.Module):
    """
    Optimized MoE Expert with Gated GEMM using HIP kernels.

    Optimizations:
    1. Fused Gate and Up projections into a single GEMM (concatenated weights).
    2. Batched processing: Tokens are sorted by expert assignment and processed in contiguous chunks per expert.
       This moves the loop logic to handle larger batches, reducing kernel launch overhead and removing 
       the inefficient masking/indexing inside the loop.
    3. Custom HIP kernel for the fused SiLU activation and elementwise multiplication.
    4. Memory layout optimization: Gather-scatter pattern is used to linearize memory access for GEMMs.
    """
    def __init__(self, hidden_size: int, intermediate_size: int, num_experts: int):
        super().__init__()
        self.hidden_size = hidden_size
        self.intermediate_size = intermediate_size
        self.num_experts = num_experts

        # Fuse gate_proj and up_proj into w13
        # Shape: (num_experts, 2 * intermediate, hidden)
        self.w13 = nn.Parameter(torch.empty(num_experts, 2 * intermediate_size, hidden_size))
        self.down_proj = nn.Parameter(torch.empty(num_experts, hidden_size, intermediate_size))

        # Initialize to match the reference implementation logic and random state
        with torch.no_grad():
             gate = torch.randn(num_experts, intermediate_size, hidden_size) * 0.02
             up = torch.randn(num_experts, intermediate_size, hidden_size) * 0.02
             self.w13.data.copy_(torch.cat([gate, up], dim=1))

             self.down_proj.data.copy_(torch.randn(num_experts, hidden_size, intermediate_size) * 0.02)

        self.silu_mul = module.silu_mul_hip

    def forward(
        self,
        x: torch.Tensor,
        expert_indices: torch.Tensor,
        expert_weights: torch.Tensor,
    ) -> torch.Tensor:
        # x: (B, S, H)
        # expert_indices: (B, S, K)
        # expert_weights: (B, S, K)

        batch, seq_len, hidden_dim = x.shape
        top_k = expert_indices.shape[-1]

        # Flatten everything to handle tokens uniformly
        # x_flat: (N, H)
        x_flat = x.view(-1, hidden_dim)
        expert_indices_flat = expert_indices.view(-1)
        expert_weights_flat = expert_weights.view(-1)

        # We need to track which original token each assignment belongs to.
        # This creates indices [0, 0, ..., 1, 1, ...] for top_k duplications.
        num_tokens = batch * seq_len
        token_indices_flat = torch.arange(num_tokens, device=x.device).unsqueeze(-1).expand(-1, top_k).reshape(-1)

        # Sort assignments by expert index. This effectively groups tokens by the expert they are routed to.
        # This allows us to process each expert's workload as a contiguous slice.
        sorted_expert_indices, sort_idx = expert_indices_flat.sort()

        # Reorder corresponding arrays based on the sort
        sorted_token_indices = token_indices_flat[sort_idx]
        sorted_weights = expert_weights_flat[sort_idx]

        # Gather all required inputs into a contiguous buffer sorted by expert
        # This permutation ensures optimal memory access patterns for the GEMMs
        x_gathered = x_flat[sorted_token_indices]

        # Buffer to store results before scattering back
        # We process in place or accumulate into this buffer
        results_flat = torch.empty_like(x_gathered)

        # Find boundaries for each expert in the sorted list.
        # unique_consecutive is efficient since the array is sorted.
        experts_present, counts = torch.unique_consecutive(sorted_expert_indices, return_counts=True)

        # Convert metadata to CPU for loop control (slicing requires CPU integers)
        experts_present_cpu = experts_present.tolist()
        counts_cpu = counts.tolist()

        start_idx = 0
        num_present_experts = len(experts_present_cpu)

        for i in range(num_present_experts):
            expert_id = experts_present_cpu[i]
            count = counts_cpu[i]
            end_idx = start_idx + count

            # Slice the gathered input for the current expert
            inp_slice = x_gathered[start_idx:end_idx]

            # 1. Combined GEMM (Gate + Up)
            # w13[expert_id] is (2*intermediate, hidden)
            # inp_slice is (count, hidden)
            # Result is (count, 2*intermediate)
            gemm1 = F.linear(inp_slice, self.w13[expert_id])

            # 2. Fused Activation (SiLU * Mul) via HIP kernel
            # Result is (count, intermediate)
            act = self.silu_mul(gemm1)

            # 3. Down Projection GEMM
            # down_proj[expert_id] is (hidden, intermediate)
            # Result is (count, hidden)
            gemm2 = F.linear(act, self.down_proj[expert_id])

            # 4. Scale by routing weights
            # element-wise multiplication with broadcasting
            w_slice = sorted_weights[start_idx:end_idx].unsqueeze(-1)
            gemm2.mul_(w_slice)

            # Store result
            results_flat[start_idx:end_idx] = gemm2

            start_idx = end_idx

        # Scatter results back to original positions
        # index_add_ sums the contributions from multiple experts to the same token
        output = torch.zeros(num_tokens, hidden_dim, device=x.device, dtype=x.dtype)
        output.index_add_(0, sorted_token_indices, results_flat)

        return output.view(batch, seq_len, hidden_dim)

