#include <hip/hip_runtime.h>
#include <hip/hip_fp16.h>
#include <hip/hip_fp8.h>
#include <torch/extension.h>

extern "C" __global__ void quantize_e4m3_kernel(
    const half* __restrict__ input, 
    void* __restrict__ output, 
    const float* __restrict__ scale_ptr, 
    int numel) 
{
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    float scale = *scale_ptr;

    if (idx < numel) {
        float val = __half2float(input[idx]);
        val = val * scale;
        // Clamp to E4M3 range [-448, 448]
        val = fmaxf(-448.0f, fminf(448.0f, val));

        // Cast to fp8 e4m3fn
        ((__float8_e4m3fn*)output)[idx] = (__float8_e4m3fn)(val);
    }
}

extern "C" __global__ void quantize_e5m2_kernel(
    const half* __restrict__ input, 
    void* __restrict__ output, 
    const float* __restrict__ scale_ptr, 
    int numel) 
{
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    float scale = *scale_ptr;

    if (idx < numel) {
        float val = __half2float(input[idx]);
        val = val * scale;
        // Clamp to E5M2 range [-57344, 57344]
        val = fmaxf(-57344.0f, fminf(57344.0f, val));

        // Cast to fp8 e5m2
        ((__float8_e5m2*)output)[idx] = (__float8_e5m2)(val);
    }
}

torch::Tensor quantize_fp8_hip(torch::Tensor input, torch::Tensor scale, bool use_e4m3) {
    auto options = torch::TensorOptions().device(input.device());
    torch::Tensor output;

    if (use_e4m3) {
        output = torch::empty(input.sizes(), options.dtype(torch::kFloat8_e4m3fn));
    } else {
        output = torch::empty(input.sizes(), options.dtype(torch::kFloat8_e5m2));
    }

    int numel = input.numel();
    int block_size = 256;
    int num_blocks = (numel + block_size - 1) / block_size;

    // Ensure input is contiguous or handle strides? 
    // Flattened input is usually contiguous.
    if (!input.is_contiguous()) {
        input = input.contiguous();
    }

    if (use_e4m3) {
        quantize_e4m3_kernel<<<num_blocks, block_size>>>(
            (half*)input.data_ptr<at::Half>(),
            output.data_ptr(),
            (float*)scale.data_ptr<float>(),
            numel
        );
    } else {
        quantize_e5m2_kernel<<<num_blocks, block_size>>>(
            (half*)input.data_ptr<at::Half>(),
            output.data_ptr(),
            (float*)scale.data_ptr<float>(),
            numel
        );
    }
    return output;
}
"""

fp8_module = load_inline(
    name="fp8_kernels",
    cpp_sources=cpp_source,
    functions=["quantize_fp8_hip"],
    extra_cflags=["-O3", "--offload-arch=native"],
    verbose=False,
)

class ModelNew(nn.Module):
    def __init__(self, M: int, K: int, N: int, use_e4m3: bool = True):
        super().__init__()
        self.M = M
        self.K = K
        self.N = N
        self.use_e4m3 = use_e4m3

        if use_e4m3:
            self.fp8_dtype = torch.float8_e4m3fn
            self.fp8_max = 448.0
        else:
            self.fp8_dtype = torch.float8_e5m2
            self.fp8_max = 57344.0

        # Weights in FP16/FP32
        self.weight = nn.Parameter(torch.randn(K, N) * 0.02)

        # Caches for pre-quantized weights
        self.weight_fp8 = None
        self.weight_scale_inv = None
        self.last_weight_version = -1

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # 1. Pre-quantize weights if needed (efficient inference)
        # We check if weights have changed or if it's the first run
        if self.weight_fp8 is None or self.weight._version != self.last_weight_version or self.weight_fp8.device != x.device:
            with torch.no_grad():
                w_amax = self.weight.abs().max()
                w_scale = self.fp8_max / w_amax.clamp(min=1e-12)

                # We use standard PyTorch for weight quantization as it is infrequent
                # Transpose first as in original forward
                w_t = self.weight.t().contiguous()
                w_scaled = w_t * w_scale
                w_clamped = w_scaled.clamp(-self.fp8_max, self.fp8_max)
                self.weight_fp8 = w_clamped.to(self.fp8_dtype)
                self.weight_scale_inv = (1.0 / w_scale).float()
                self.last_weight_version = self.weight._version

        batch_size = x.shape[0]
        seq_len = x.shape[1]

        # Reshape: (batch, seq, K) -> (batch*seq, K)
        x_2d = x.view(-1, self.K)

        # 2. Dynamic Input Quantization
        # Compute scale (GPU reduction)
        amax = x_2d.abs().max()
        scale = self.fp8_max / amax.clamp(min=1e-12)

        # Ensure input is half for kernel
        x_in = x_2d
        if x_in.dtype != torch.float16:
            x_in = x_in.half()

        # Custom fused kernel: Scale + Clamp + Cast
        # Avoids CPU sync by passing scale tensor
        x_fp8 = fp8_module.quantize_fp8_hip(x_in, scale, self.use_e4m3)

        # Inverse scale for _scaled_mm
        x_scale_inv = (1.0 / scale).float()

        # 3. FP8 GEMM
        # _scaled_mm(A, B.T, scale_a, scale_b)
        # x_fp8: (M, K)
        # weight_fp8: (N, K) -> t() -> (K, N)
        # output: (M, N)
        out = torch._scaled_mm(
            x_fp8,
            self.weight_fp8.t(), 
            scale_a=x_scale_inv,
            scale_b=self.weight_scale_inv,
            out_dtype=x.dtype
        )

        return out.view(batch_size, seq_len, self.N)

