def rotate_half(x):
    """Rotates half the hidden dims of the input."""
    x1 = x[..., : x.shape[-1] // 2]
    x2 = x[..., x.shape[-1] // 2 :]
    return torch.cat((-x2, x1), dim=-1)


def apply_rotary_pos_emb(q, k, cos, sin):
    """Apply rotary positional embeddings."""
    q_embed = (q * cos) + (rotate_half(q) * sin)
    k_embed = (k * cos) + (rotate_half(k) * sin)
    return q_embed, k_embed


class RotaryEmbedding(nn.Module):
    def __init__(self, dim, max_position_embeddings=4096, base=10000.0):
        super().__init__()
        self.dim = dim
        self.max_position_embeddings = max_position_embeddings
        self.base = base
        inv_freq = 1.0 / (self.base ** (torch.arange(0, self.dim, 2, dtype=torch.float32) / self.dim))
        self.register_buffer("inv_freq", inv_freq, persistent=False)

    @torch.no_grad()
    def forward(self, x, seq_len=None):
        if seq_len is None:
            seq_len = x.shape[-2]
        t = torch.arange(seq_len, device=x.device, dtype=torch.float32)
        freqs = torch.outer(t, self.inv_freq)
        emb = torch.cat((freqs, freqs), dim=-1)
        return emb.cos().unsqueeze(0).unsqueeze(0), emb.sin().unsqueeze(0).unsqueeze(0)

cpp_source = """
#include <hip/hip_runtime.h>
#include <hip/hip_fp16.h>

#define WARP_SIZE 64
#define HEAD_DIM 128
#define TILE_K 32
#define QUERIES_PER_BLOCK 4

__global__ void gqa_kernel(
    const float* __restrict__ Q,
    const float* __restrict__ K,
    const float* __restrict__ V,
    float* __restrict__ Out,
    const int stride_q_b, const int stride_q_h, const int stride_q_l, const int stride_q_d,
    const int stride_k_b, const int stride_k_h, const int stride_k_l, const int stride_k_d,
    const int stride_v_b, const int stride_v_h, const int stride_v_l, const int stride_v_d,
    const int stride_o_b, const int stride_o_h, const int stride_o_l, const int stride_o_d,
    const int num_kv_groups,
    const int seq_len,
    const float scale)
{
    // Grid: x=Chunk, y=HeadQ, z=Batch
    // Block: x=64 (Lane), y=4 (Warp)

    int batch_idx = blockIdx.z;
    int head_q_idx = blockIdx.y;
    int head_kv_idx = head_q_idx / num_kv_groups;

    int q_chunk_idx = blockIdx.x;
    int warp_idx = threadIdx.y; 
    int tid = threadIdx.x;

    int q_global_idx = q_chunk_idx * QUERIES_PER_BLOCK + warp_idx;

    __shared__ float s_K[TILE_K][HEAD_DIM];
    __shared__ float s_V[TILE_K][HEAD_DIM];

    float q_val[2] = {0.0f, 0.0f};
    float out_val[2] = {0.0f, 0.0f};

    // Load Q
    if (q_global_idx < seq_len) {
        long long q_base = (long long)batch_idx * stride_q_b + 
                           (long long)head_q_idx * stride_q_h + 
                           (long long)q_global_idx * stride_q_l;
        q_val[0] = Q[q_base + tid * stride_q_d];
        q_val[1] = Q[q_base + (tid + 64) * stride_q_d];
    }

    float max_score = -1e30f;
    float sum_exp = 0.0f;

    int num_tiles = (seq_len + TILE_K - 1) / TILE_K;

    for (int t = 0; t < num_tiles; ++t) {
        int t_offset = t * TILE_K;

        // Load K/V to Shared
        int flat_tid = warp_idx * WARP_SIZE + tid; // 0..255

        // Each thread loads 16 floats (4096 total floats / 256 threads)
        #pragma unroll
        for (int i = 0; i < 16; ++i) {
            int linear_idx = flat_tid * 16 + i;
            if (linear_idx < TILE_K * HEAD_DIM) {
                int k_row = linear_idx / HEAD_DIM;
                int k_col = linear_idx % HEAD_DIM;
                int time_idx = t_offset + k_row;

                if (time_idx < seq_len) {
                    long long k_base = (long long)batch_idx * stride_k_b + 
                                       (long long)head_kv_idx * stride_k_h + 
                                       (long long)time_idx * stride_k_l;
                    long long v_base = (long long)batch_idx * stride_v_b + 
                                       (long long)head_kv_idx * stride_v_h + 
                                       (long long)time_idx * stride_v_l;

                    s_K[k_row][k_col] = K[k_base + k_col * stride_k_d];
                    s_V[k_row][k_col] = V[v_base + k_col * stride_v_d];
                } else {
                    s_K[k_row][k_col] = 0.0f;
                    s_V[k_row][k_col] = 0.0f;
                }
            }
        }
        __syncthreads();

        if (q_global_idx < seq_len) {
            int valid_k_in_tile = min(TILE_K, seq_len - t_offset);

            for (int k = 0; k < valid_k_in_tile; ++k) {
                int curr_k_idx = t_offset + k;

                if (curr_k_idx > q_global_idx) continue; // Causal

                float val_k0 = s_K[k][tid];
                float val_k1 = s_K[k][tid + 64];

                float dot = q_val[0] * val_k0 + q_val[1] * val_k1;

                // Warp Reduce
                for (int off = 32; off > 0; off /= 2) {
                    dot += __shfl_xor(dot, off);
                }

                float score = dot * scale;

                float new_max = max(max_score, score);
                float exp_s = expf(score - new_max);
                float correction = expf(max_score - new_max);

                max_score = new_max;
                sum_exp = sum_exp * correction + exp_s;

                float val_v0 = s_V[k][tid];
                float val_v1 = s_V[k][tid + 64];

                out_val[0] = out_val[0] * correction + exp_s * val_v0;
                out_val[1] = out_val[1] * correction + exp_s * val_v1;
            }
        }
        __syncthreads();
    }

    if (q_global_idx < seq_len) {
        float inv_sum = 1.0f / (sum_exp + 1e-6f);
        out_val[0] *= inv_sum;
        out_val[1] *= inv_sum;

        long long out_base = (long long)batch_idx * stride_o_b + 
                             (long long)head_q_idx * stride_o_h + 
                             (long long)q_global_idx * stride_o_l;
        Out[out_base + tid * stride_o_d] = out_val[0];
        Out[out_base + (tid + 64) * stride_o_d] = out_val[1];
    }
}

torch::Tensor gqa_forward(
    torch::Tensor Q,
    torch::Tensor K,
    torch::Tensor V,
    double scale) 
{
