    auto H_Q = Q.size(1);
    auto L = Q.size(2);
    auto D = Q.size(3);
    auto H_KV = K.size(1);

    auto Out = torch::empty_like(Q);

    int group_size = H_Q / H_KV;

    int queries_per_block = 4;
    dim3 grid((L + queries_per_block - 1) / queries_per_block, H_Q, B);
    dim3 block(64, 4); // 64 lanes, 4 warps

    gqa_kernel<<<grid, block>>>(
        Q.data_ptr<float>(),
        K.data_ptr<float>(),
        V.data_ptr<float>(),
        Out.data_ptr<float>(),
        Q.stride(0), Q.stride(1), Q.stride(2), Q.stride(3),
        K.stride(0), K.stride(1), K.stride(2), K.stride(3),
        V.stride(0), V.stride(1), V.stride(2), V.stride(3),
        Out.stride(0), Out.stride(1), Out.stride(2), Out.stride(3),
        group_size,
        L,
        (float)scale
    );

    return Out;
}
