cpp_source = """
#include <hip/hip_runtime.h>

__global__ void rms_norm_kernel(
    const float* __restrict__ x,
    const float* __restrict__ weight,
    float* __restrict__ y,
    int size,
    float eps,
    int num_rows
) {
    int row = blockIdx.x;
    if (row >= num_rows) return;

    const float* row_x = x + row * size;
    float* row_y = y + row * size;

    float sum_sq = 0.0f;
    for (int i = threadIdx.x; i < size; i += blockDim.x) {
        float val = row_x[i];
        sum_sq += val * val;
    }

    extern __shared__ float sdata[];
    int tid = threadIdx.x;
    sdata[tid] = sum_sq;
    __syncthreads();

    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            sdata[tid] += sdata[tid + s];
        }
        __syncthreads();
    }

    float mean = sdata[0] / size;
    float inv_rms = rsqrtf(mean + eps);

    for (int i = threadIdx.x; i < size; i += blockDim.x) {
        row_y[i] = row_x[i] * inv_rms * weight[i];
    }
}

__global__ void mla_assembly_kernel(
    const float* __restrict__ q_in,      
    const float* __restrict__ kv_in,     
    const float* __restrict__ k_pe_in,   
    const float* __restrict__ cos,       
    const float* __restrict__ sin,       
    float* __restrict__ q_out,           
    float* __restrict__ k_out,           
    float* __restrict__ v_out,           
    int bsz, int seq_len, int num_heads,
    int q_head_dim, int nope_dim, int rope_dim, int v_dim
) {
    // Grid is linear: idx = b * (num_heads * seq_len) + h * seq_len + s
    int idx = blockIdx.x;

    int s = idx % seq_len;
    int temp = idx / seq_len;
    int h = temp % num_heads;
    int b = temp / num_heads;

    int tid = threadIdx.x;

    // Offsets
    // q_in: [b, s, h, q_head_dim]
    long long q_in_base = (long long)b * seq_len * num_heads * q_head_dim + 
                          (long long)s * num_heads * q_head_dim + 
                          (long long)h * q_head_dim;

    // kv_in: [b, s, h, nope_dim + v_dim]
    int kv_dim = nope_dim + v_dim;
    long long kv_in_base = (long long)b * seq_len * num_heads * kv_dim + 
                           (long long)s * num_heads * kv_dim + 
                           (long long)h * kv_dim;

    // k_pe_in: [b, s, rope_dim]
    long long k_pe_base = (long long)b * seq_len * rope_dim + 
                          (long long)s * rope_dim;

    // Outputs: [b, h, s, dim]
    long long q_out_base = (long long)b * num_heads * seq_len * q_head_dim + 
                           (long long)h * seq_len * q_head_dim + 
                           (long long)s * q_head_dim;

    long long k_out_base = q_out_base; 

    long long v_out_base = (long long)b * num_heads * seq_len * v_dim + 
                           (long long)h * seq_len * v_dim + 
                           (long long)s * v_dim;

    const float* c_ptr = cos + s * rope_dim;
    const float* s_ptr = sin + s * rope_dim;

    // 1. Process Q
    if (tid < q_head_dim) {
        float val = q_in[q_in_base + tid];

        if (tid >= nope_dim) {
            int pe_idx = tid - nope_dim; 
            int half_rope = rope_dim / 2;

            float cc = c_ptr[pe_idx % half_rope];
            float ss = s_ptr[pe_idx % half_rope];

            int pair_offset;
            if (pe_idx < half_rope) pair_offset = half_rope;
            else pair_offset = -half_rope;

            float val_pair = q_in[q_in_base + nope_dim + pe_idx + pair_offset];

            if (pe_idx < half_rope) {
                val = val * cc - val_pair * ss;
            } else {
                val = val * cc + val_pair * ss;
            }
        }
        q_out[q_out_base + tid] = val;
    }

    // 2. Process K
    if (tid < q_head_dim) {
        float val;
        if (tid < nope_dim) {
            val = kv_in[kv_in_base + tid];
        } else {
            int pe_idx = tid - nope_dim;
            val = k_pe_in[k_pe_base + pe_idx];

            int half_rope = rope_dim / 2;
            float cc = c_ptr[pe_idx % half_rope];
            float ss = s_ptr[pe_idx % half_rope];

            int pair_offset;
            if (pe_idx < half_rope) pair_offset = half_rope;
            else pair_offset = -half_rope;

            float val_pair = k_pe_in[k_pe_base + pe_idx + pair_offset];

            if (pe_idx < half_rope) {
                val = val * cc - val_pair * ss;
            } else {
                val = val * cc + val_pair * ss;
            }
        }
        k_out[k_out_base + tid] = val;
    }

    // 3. Process V
    if (tid < v_dim) {
        v_out[v_out_base + tid] = kv_in[kv_in_base + nope_dim + tid];
    }
}

torch::Tensor rms_norm_cuda(torch::Tensor x, torch::Tensor weight, float eps) {
    auto y = torch::empty_like(x);
    int size = x.size(-1);
    int num_rows = x.numel() / size;

    const int block_size = 256;
    rms_norm_kernel<<<num_rows, block_size, block_size * sizeof(float)>>>(
        x.data_ptr<float>(),
        weight.data_ptr<float>(),
        y.data_ptr<float>(),
        size,
        eps,
        num_rows
    );
    return y;
}

std::vector<torch::Tensor> mla_assembly_cuda(
    torch::Tensor q_in,
    torch::Tensor kv_in,
    torch::Tensor k_pe_in,
    torch::Tensor cos,
    torch::Tensor sin,
    int num_heads,
    int q_head_dim,
    int nope_dim,
    int rope_dim,
    int v_dim
) {
    int bsz = q_in.size(0);
    int seq_len = q_in.size(1);

    auto options = q_in.options();
    auto q_out = torch::empty({bsz, num_heads, seq_len, q_head_dim}, options);
    auto k_out = torch::empty({bsz, num_heads, seq_len, q_head_dim}, options);
    auto v_out = torch::empty({bsz, num_heads, seq_len, v_dim}, options);

    int total_blocks = bsz * num_heads * seq_len;
    const int block_size = 256;

    mla_assembly_kernel<<<total_blocks, block_size>>>(
        q_in.data_ptr<float>(),
        kv_in.data_ptr<float>(),
        k_pe_in.data_ptr<float>(),
        cos.data_ptr<float>(),
        sin.data_ptr<float>(),
        q_out.data_ptr<float>(),
        k_out.data_ptr<float>(),
        v_out.data_ptr<float>(),
        bsz, seq_len, num_heads,
        q_head_dim, nope_dim, rope_dim, v_dim
    );

    return {q_out, k_out, v_out};
}
"""

mla_kernels = load_inline(
    name="mla_kernels",
    cpp_sources=cpp_source,
    functions=["rms_norm_cuda", "mla_assembly_cuda"],
    verbose=True,
)

class DeepSeekRMSNorm(nn.Module):
    def __init__(self, hidden_size, eps=1e-6):
        super().__init__()
        self.weight = nn.Parameter(torch.ones(hidden_size))
        self.variance_epsilon = eps

    def forward(self, hidden_states):
        # We can optimize this but for now let's just use the kernel via ModelNew
        # Or if this is called directly, use pytorch.
        # But we will replace usages in ModelNew.
        input_dtype = hidden_states.dtype
        hidden_states = hidden_states.to(torch.float32)
        variance = hidden_states.pow(2).mean(-1, keepdim=True)
        hidden_states = hidden_states * torch.rsqrt(variance + self.variance_epsilon)
        return self.weight * hidden_states.to(input_dtype)

class DeepSeekRotaryEmbedding(nn.Module):
    def __init__(self, dim, max_position_embeddings=2048, base=10000.0):
        super().__init__()
        self.dim = dim
        self.max_position_embeddings = max_position_embeddings
        self.base = base
        inv_freq = 1.0 / (self.base ** (torch.arange(0, self.dim, 2, dtype=torch.float32) / self.dim))
        self.register_buffer("inv_freq", inv_freq, persistent=False)

    @torch.no_grad()
    def forward(self, x, seq_len=None):
        if seq_len is None:
            seq_len = x.shape[-2]
        t = torch.arange(seq_len, device=x.device, dtype=torch.float32)
        freqs = torch.outer(t, self.inv_freq)
        emb = torch.cat((freqs, freqs), dim=-1)
        return emb.cos(), emb.sin()

class ModelNew(nn.Module):
    def __init__(
        self,
        hidden_size: int,
        num_attention_heads: int,
        q_lora_rank: int,
        kv_lora_rank: int,
        qk_nope_head_dim: int,
        qk_rope_head_dim: int,
        v_head_dim: int,
        max_position_embeddings: int = 2048,
        rope_theta: float = 10000.0,
        attention_dropout: float = 0.0,
    ):
        super().__init__()
        self.hidden_size = hidden_size
        self.num_heads = num_attention_heads
        self.q_lora_rank = q_lora_rank
        self.kv_lora_rank = kv_lora_rank
        self.qk_nope_head_dim = qk_nope_head_dim
        self.qk_rope_head_dim = qk_rope_head_dim
        self.v_head_dim = v_head_dim
        self.q_head_dim = qk_nope_head_dim + qk_rope_head_dim
        self.attention_dropout = attention_dropout
        self.softmax_scale = self.q_head_dim ** (-0.5)

        self.q_a_proj = nn.Linear(hidden_size, q_lora_rank, bias=False)
        self.q_a_layernorm = DeepSeekRMSNorm(q_lora_rank)
        self.q_b_proj = nn.Linear(q_lora_rank, num_attention_heads * self.q_head_dim, bias=False)

        self.kv_a_proj_with_mqa = nn.Linear(
            hidden_size, kv_lora_rank + qk_rope_head_dim, bias=False
        )
        self.kv_a_layernorm = DeepSeekRMSNorm(kv_lora_rank)
        self.kv_b_proj = nn.Linear(
            kv_lora_rank,
            num_attention_heads * (qk_nope_head_dim + v_head_dim),
            bias=False,
        )

        self.o_proj = nn.Linear(num_attention_heads * v_head_dim, hidden_size, bias=False)

        self.rotary_emb = DeepSeekRotaryEmbedding(
            qk_rope_head_dim,
            max_position_embeddings=max_position_embeddings,
            base=rope_theta,
        )

    def forward(self, hidden_states: torch.Tensor) -> torch.Tensor:
        bsz, q_len, _ = hidden_states.size()

        # 1. Q Projection
        # q_a_proj
        q_compressed = self.q_a_proj(hidden_states)

        # RMSNorm fused
        # q_compressed = self.q_a_layernorm(q_compressed)
        q_compressed = mla_kernels.rms_norm_cuda(
            q_compressed, 
            self.q_a_layernorm.weight, 
            self.q_a_layernorm.variance_epsilon
        )

        q = self.q_b_proj(q_compressed)
        # q is [bsz, q_len, num_heads * q_head_dim]
        # View to [bsz, q_len, num_heads, q_head_dim]
        q = q.view(bsz, q_len, self.num_heads, self.q_head_dim)

        # 2. KV Projection
        compressed_kv = self.kv_a_proj_with_mqa(hidden_states)

        # Split compressed_kv
        # This split is needed to get k_pe.
        # compressed_kv is [bsz, q_len, kv_lora_rank + qk_rope_head_dim]
        # split -> [bsz, q_len, kv_lora_rank], [bsz, q_len, qk_rope_head_dim]
        # The split copies memory usually, but slicing doesn't.
        # k_pe needs to be contiguous for the kernel if we pass pointer.
        # compressed_kv_main = compressed_kv[..., :self.kv_lora_rank]
        # k_pe = compressed_kv[..., self.kv_lora_rank:]

        compressed_kv_main, k_pe = torch.split(
            compressed_kv, [self.kv_lora_rank, self.qk_rope_head_dim], dim=-1
        )

        # RMSNorm on compressed_kv_main
        compressed_kv_main = mla_kernels.rms_norm_cuda(
            compressed_kv_main.contiguous(),
            self.kv_a_layernorm.weight,
            self.kv_a_layernorm.variance_epsilon
        )

        # kv_b_proj
        kv = self.kv_b_proj(compressed_kv_main)
        # kv is [bsz, q_len, num_heads * (nope + v)]
        kv = kv.view(bsz, q_len, self.num_heads, self.qk_nope_head_dim + self.v_head_dim)

        # 3. RoPE and Assembly
        cos, sin = self.rotary_emb(kv, seq_len=q_len) # kv passed just for device

        # Run fused assembly
        # Need k_pe contiguous
        k_pe = k_pe.contiguous()

        query_states, key_states, value_states = mla_kernels.mla_assembly_cuda(
            q,
            kv,
            k_pe,
            cos,
            sin,
            self.num_heads,
            self.q_head_dim,
            self.qk_nope_head_dim,
            self.qk_rope_head_dim,
            self.v_head_dim
        )

        # 4. Attention
        # query_states: [bsz, num_heads, seq, q_head_dim]
        # key_states: [bsz, num_heads, seq, q_head_dim]
        # value_states: [bsz, num_heads, seq, v_dim]

        attn_weights = torch.matmul(query_states, key_states.transpose(2, 3)) * self.softmax_scale

        causal_mask = torch.triu(
            torch.ones(q_len, q_len, device=hidden_states.device, dtype=torch.bool),
            diagonal=1
        )
        attn_weights = attn_weights.masked_fill(causal_mask, float('-inf'))

        attn_weights = F.softmax(attn_weights, dim=-1, dtype=torch.float32).to(query_states.dtype)
        attn_weights = F.dropout(attn_weights, p=self.attention_dropout, training=self.training)

        attn_output = torch.matmul(attn_weights, value_states)

        # 5. Output projection
        # attn_output: [bsz, num_heads, seq, v_dim]
        # Transpose and reshape
        attn_output = attn_output.transpose(1, 2).contiguous()
        attn_output = attn_output.reshape(bsz, q_len, self.num_heads * self.v_head_dim)
        attn_output = self.o_proj(attn_output)

        return attn_output

import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline
import os

# Set compiler to hipcc
os.environ["CXX"] = "hipcc"

cpp_source = """
#include <hip/hip_runtime.h>
#include <hip/hip_fp16.h>
#include <torch/extension.h>

#define BM 64
#define BN 64
#define BK 32
#define GROUP_SIZE 128

__device__ inline void unpack_and_dequant(
    uint32_t packed, 
    half scale, 
    half* dst, 
    int offset
) {
    uchar4 bytes = *reinterpret_cast<uchar4*>(&packed);

    float s = __half2float(scale);
    float bias = s * 8.0f;

    float w0 = s * (float)(bytes.x & 0xF) - bias;
    float w1 = s * (float)(bytes.x >> 4) - bias;
    float w2 = s * (float)(bytes.y & 0xF) - bias;
    float w3 = s * (float)(bytes.y >> 4) - bias;
    float w4 = s * (float)(bytes.z & 0xF) - bias;
    float w5 = s * (float)(bytes.z >> 4) - bias;
    float w6 = s * (float)(bytes.w & 0xF) - bias;
    float w7 = s * (float)(bytes.w >> 4) - bias;

    dst[offset + 0] = __float2half(w0);
    dst[offset + 1] = __float2half(w1);
    dst[offset + 2] = __float2half(w2);
    dst[offset + 3] = __float2half(w3);
    dst[offset + 4] = __float2half(w4);
    dst[offset + 5] = __float2half(w5);
    dst[offset + 6] = __float2half(w6);
    dst[offset + 7] = __float2half(w7);
}

__global__ void gemm_int4_f16_kernel(
    const half* __restrict__ A,
    const uint8_t* __restrict__ B_packed,
    const half* __restrict__ Scales,
    half* __restrict__ C,
    int M, int N, int K, int num_groups) 
{
    int bx = blockIdx.x; 
    int by = blockIdx.y; 

    int tid = threadIdx.x;

    __shared__ half As[BM][BK];
    __shared__ half Bs[BN][BK];

    float acc[4][4] = {0.0f};

    int row_A = by * BM;
    int row_B = bx * BN;

    int ty = tid / 16;
    int tx = tid % 16;

    for (int k = 0; k < K; k += BK) {
        // Load A
        int load_a_row = tid >> 2;
        int load_a_col = (tid & 3) << 3;

        // Check bounds for A load if M is not multiple of BM
        // But A is contiguous (M, K). 
        // We load from (row_A + load_a_row, k + load_a_col)
        // If row_A + load_a_row >= M, we should load 0?
        // Or rely on padding/multiples. 
        // For performance, we assume M is large enough or padded, or handle carefully.
        // Given the problem constraints and typical LLM usage, we can assume valid access or rely on bounds check during computation.
        // However, reading out of bounds might segfault.
        // Let's add simple guard: if row out of bounds, load 0.

        int r_a = row_A + load_a_row;
        int c_a = k + load_a_col;
        float4 a_val;
        if (r_a < M && c_a < K) { // K is multiple of 32, so c_a check is likely safe if K aligned
             const float4* A_ptr = reinterpret_cast<const float4*>(&A[r_a * K + c_a]);
             a_val = *A_ptr;
        } else {
             // Zero out
             a_val = make_float4(0,0,0,0); // Assuming this works or memset
             // float4 doesn't have constructor in HIP/CUDA like this? 
             // Just set to 0.
             half* ptr = (half*)&a_val; 
             ptr[0] = __float2half(0); ptr[1] = __float2half(0); 
             ptr[2] = __float2half(0); ptr[3] = __float2half(0);
             ptr[4] = __float2half(0); ptr[5] = __float2half(0);
             ptr[6] = __float2half(0); ptr[7] = __float2half(0);
        }

        half* As_ptr = &As[load_a_row][load_a_col];
        *reinterpret_cast<float4*>(As_ptr) = a_val;

        // Load B
        int load_b_row = tid >> 2;
        int load_b_col_byte = (tid & 3) * 4;

        int r_b = row_B + load_b_row;
        // B_packed is (N, K/2).
        // If r_b < N...

        uint32_t b_val = 0;
        half scale = __float2half(0.0f);

        if (r_b < N) {
             const uint32_t* B_ptr = reinterpret_cast<const uint32_t*>(
                 &B_packed[r_b * (K / 2) + (k / 2) + load_b_col_byte]
             );
             b_val = *B_ptr;

             int group_idx = k / GROUP_SIZE;
             scale = Scales[r_b * num_groups + group_idx];
        }

        unpack_and_dequant(b_val, scale, &Bs[load_b_row][load_b_col_byte * 2], 0);

        __syncthreads();

        #pragma unroll
        for (int bk = 0; bk < BK; ++bk) {
            half a_reg[4];
            a_reg[0] = As[ty * 4 + 0][bk];
            a_reg[1] = As[ty * 4 + 1][bk];
            a_reg[2] = As[ty * 4 + 2][bk];
            a_reg[3] = As[ty * 4 + 3][bk];

            half b_reg[4];
            b_reg[0] = Bs[tx * 4 + 0][bk];
            b_reg[1] = Bs[tx * 4 + 1][bk];
            b_reg[2] = Bs[tx * 4 + 2][bk];
            b_reg[3] = Bs[tx * 4 + 3][bk];

            for (int i = 0; i < 4; ++i) {
                for (int j = 0; j < 4; ++j) {
                    acc[i][j] += __half2float(a_reg[i]) * __half2float(b_reg[j]);
                }
            }
        }

        __syncthreads();
    }

    int c_row_start = by * BM + ty * 4;
    int c_col_start = bx * BN + tx * 4;

    #pragma unroll
    for (int i = 0; i < 4; ++i) {
        #pragma unroll
        for (int j = 0; j < 4; ++j) {
            int r = c_row_start + i;
            int c = c_col_start + j;
            if (r < M && c < N) {
                C[r * N + c] = __float2half(acc[i][j]);
            }
        }
    }
}

void gemm_int4_f16_launcher(
    torch::Tensor A,
    torch::Tensor B_packed,
    torch::Tensor Scales,
    torch::Tensor C,
    int M, int N, int K, int num_groups) 
{
    const half* A_ptr = reinterpret_cast<const half*>(A.data_ptr<at::Half>());
    const uint8_t* B_ptr = B_packed.data_ptr<uint8_t>();
    const half* Scales_ptr = reinterpret_cast<const half*>(Scales.data_ptr<at::Half>());
    half* C_ptr = reinterpret_cast<half*>(C.data_ptr<at::Half>());

    dim3 block(256, 1, 1);
    dim3 grid((N + BN - 1) / BN, (M + BM - 1) / BM);

    gemm_int4_f16_kernel<<<grid, block>>>(A_ptr, B_ptr, Scales_ptr, C_ptr, M, N, K, num_groups);
}
"""

class ModelNew(nn.Module):
    def __init__(self, K: int, N: int, group_size: int = 128):
        super().__init__()
        self.K = K
        self.N = N
        self.group_size = group_size
        self.num_groups = K // group_size

        assert group_size == 128, "Kernel optimized for group_size=128"
        assert K % 32 == 0, "K must be multiple of 32"

        self.register_buffer(
            "weight_packed",
            torch.randint(0, 256, (N, K // 2), dtype=torch.uint8)
        )

        self.register_buffer(
            "scales",
            torch.randn(N, self.num_groups, dtype=torch.float16).abs() * 0.1
        )

        self.int4_gemm = load_inline(
            name="int4_gemm",
            cpp_sources=cpp_source,
            functions=["gemm_int4_f16_launcher"],
            verbose=False,
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        batch_size, seq_len, _ = x.shape
        M = batch_size * seq_len

        x_cont = x.contiguous().view(-1, self.K)

        out = torch.empty((M, self.N), device=x.device, dtype=torch.float16)

        self.int4_gemm.gemm_int4_f16_launcher(
            x_cont,
            self.weight_packed,
            self.scales,
            out,
            M, self.N, self.K, self.num_groups
        )

        return out.view(batch_size, seq_len, self.N)

# Configuration sized for LLM inference workloads
batch_size = 4
seq_len = 2048
K = 4096         # Input features (hidden dim)
N = 11008        # Output features (MLP intermediate, typical for 7B models)
group_size = 128 # Standard group size for GPTQ

def get_inputs():
    return [torch.randn(batch_size, seq_len, K, dtype=torch.float16).cuda()]

def get_init_inputs():
    return [K, N, group_size]

import torch
import torch.nn as nn
import torch.nn.functional as F
import math
import os
from torch.utils.cpp_extension import load_inline

# Set compiler to hipcc
