def rotate_half(x):
    x1 = x[..., : x.shape[-1] // 2]
    x2 = x[..., x.shape[-1] // 2 :]
    return torch.cat((-x2, x1), dim=-1)

def apply_rotary_pos_emb(q, k, cos, sin):
    q_embed = (q * cos) + (rotate_half(q) * sin)
    k_embed = (k * cos) + (rotate_half(k) * sin)
    return q_embed, k_embed

class RotaryEmbedding(nn.Module):
    def __init__(self, dim, max_position_embeddings=4096, base=10000.0):
        super().__init__()
        self.dim = dim
        self.max_position_embeddings = max_position_embeddings
        self.base = base
        inv_freq = 1.0 / (self.base ** (torch.arange(0, self.dim, 2, dtype=torch.float32) / self.dim))
        self.register_buffer("inv_freq", inv_freq, persistent=False)

    @torch.no_grad()
    def forward(self, x, seq_len=None):
        if seq_len is None:
            seq_len = x.shape[-2]
        t = torch.arange(seq_len, device=x.device, dtype=torch.float32)
        freqs = torch.outer(t, self.inv_freq)
        emb = torch.cat((freqs, freqs), dim=-1)
        return emb.cos().unsqueeze(0).unsqueeze(0), emb.sin().unsqueeze(0).unsqueeze(0)

cpp_source = """
#include <hip/hip_runtime.h>
#include <hip/hip_fp16.h>

#define TILE_Q 64
#define TILE_K 16
#define HEAD_DIM 128
#define HEAD_DIM_PAD 132
#define THREADS_PER_Q 4

__global__ void gqa_kernel_opt(
    const float* __restrict__ Q,
    const float* __restrict__ K,
    const float* __restrict__ V,
    float* __restrict__ Out,
    const int stride_q_b, const int stride_q_h, const int stride_q_l, const int stride_q_d,
    const int stride_k_b, const int stride_k_h, const int stride_k_l, const int stride_k_d,
    const int stride_v_b, const int stride_v_h, const int stride_v_l, const int stride_v_d,
    const int stride_o_b, const int stride_o_h, const int stride_o_l, const int stride_o_d,
    const int num_kv_groups,
    const int seq_len,
    const float scale)
{
    int batch_idx = blockIdx.z;
    int head_q_idx = blockIdx.y;
    int head_kv_idx = head_q_idx / num_kv_groups;
    int q_chunk_idx = blockIdx.x;

    int tid = threadIdx.x; // 0..255

    __shared__ float s_Q[TILE_Q][HEAD_DIM_PAD];
    __shared__ float s_K[TILE_K][HEAD_DIM_PAD];
    __shared__ float s_V[TILE_K][HEAD_DIM_PAD];

    int q_start = q_chunk_idx * TILE_Q;

    // Load Q
    long long q_base_offset = (long long)batch_idx * stride_q_b + (long long)head_q_idx * stride_q_h;

    #pragma unroll
    for (int i = 0; i < 32; ++i) {
        int idx_linear = tid + i * 256;
        if (idx_linear < TILE_Q * HEAD_DIM) {
            int r = idx_linear / HEAD_DIM;
            int c = idx_linear % HEAD_DIM;
            int q_idx_global = q_start + r;
            if (q_idx_global < seq_len) {
                s_Q[r][c] = Q[q_base_offset + (long long)q_idx_global * stride_q_l + c * stride_q_d];
            } else {
                s_Q[r][c] = 0.0f;
            }
        }
    }

    // Initial Sync not needed for Q as we compute only after load
    // But we need to sync before computing
    // We also use s_K/s_V which need loop sync.
    // Let's just put one sync after Q load.
    __syncthreads();

    int q_local = tid / THREADS_PER_Q; // 0..63
    int lane = tid % THREADS_PER_Q; // 0..3

    float my_out[32];
    #pragma unroll
    for(int i=0; i<32; ++i) my_out[i] = 0.0f;

    float max_score = -1e30f;
    float sum_exp = 0.0f;

    int num_k_tiles = (seq_len + TILE_K - 1) / TILE_K;
    long long k_base_offset = (long long)batch_idx * stride_k_b + (long long)head_kv_idx * stride_k_h;
    long long v_base_offset = (long long)batch_idx * stride_v_b + (long long)head_kv_idx * stride_v_h;

    for (int t = 0; t < num_k_tiles; ++t) {
        int k_start = t * TILE_K;

        // Wait for previous iteration to be done with s_K/s_V
        __syncthreads(); 

        // Load K, V
        #pragma unroll
        for (int i = 0; i < 8; ++i) {
            int idx_linear = tid + i * 256;
            if (idx_linear < TILE_K * HEAD_DIM) {
                int r = idx_linear / HEAD_DIM;
                int c = idx_linear % HEAD_DIM;
                int k_idx_global = k_start + r;
                if (k_idx_global < seq_len) {
                    s_K[r][c] = K[k_base_offset + (long long)k_idx_global * stride_k_l + c * stride_k_d];
                    s_V[r][c] = V[v_base_offset + (long long)k_idx_global * stride_v_l + c * stride_v_d];
                } else {
                    s_K[r][c] = 0.0f;
                    s_V[r][c] = 0.0f;
                }
            }
        }
        __syncthreads();

        // Compute
        if (q_start + q_local < seq_len) {
            int q_idx_g = q_start + q_local;

            for (int k = 0; k < TILE_K; ++k) {
                int k_idx_g = k_start + k;
                if (k_idx_g >= seq_len) break;

                if (k_idx_g > q_idx_g) continue;

                float dot = 0.0f;
                #pragma unroll
                for (int i = 0; i < 32; ++i) {
                    int d = i * 4 + lane; 
                    dot += s_Q[q_local][d] * s_K[k][d];
                }

                dot += __shfl_xor(dot, 1);
                dot += __shfl_xor(dot, 2);

                float score = dot * scale;
                float new_max = max(max_score, score);
                float exp_s = expf(score - new_max);
                float correction = expf(max_score - new_max);

                max_score = new_max;
                sum_exp = sum_exp * correction + exp_s;

                #pragma unroll
                for (int i = 0; i < 32; ++i) {
                    int d = i * 4 + lane;
                    my_out[i] = my_out[i] * correction + exp_s * s_V[k][d];
                }
            }
        }
    }

    if (q_start + q_local < seq_len) {
        float inv_sum = 1.0f / (sum_exp + 1e-6f);
        long long out_base = (long long)batch_idx * stride_o_b + 
                             (long long)head_q_idx * stride_o_h + 
                             (long long)(q_start + q_local) * stride_o_l;

        #pragma unroll
        for (int i = 0; i < 32; ++i) {
             int d = i * 4 + lane;
             Out[out_base + d * stride_o_d] = my_out[i] * inv_sum;
        }
    }
}

torch::Tensor gqa_forward(
    torch::Tensor Q,
    torch::Tensor K,
    torch::Tensor V,
    double scale) 
{
    auto B = Q.size(0);
    auto H_Q = Q.size(1);
    auto L = Q.size(2);
    auto H_KV = K.size(1);

    auto Out = torch::empty_like(Q);
    int group_size = H_Q / H_KV;

    dim3 grid((L + 63) / 64, H_Q, B);
    dim3 block(256); 

    gqa_kernel_opt<<<grid, block>>>(
        Q.data_ptr<float>(),
        K.data_ptr<float>(),
        V.data_ptr<float>(),
        Out.data_ptr<float>(),
        Q.stride(0), Q.stride(1), Q.stride(2), Q.stride(3),
        K.stride(0), K.stride(1), K.stride(2), K.stride(3),
        V.stride(0), V.stride(1), V.stride(2), V.stride(3),
        Out.stride(0), Out.stride(1), Out.stride(2), Out.stride(3),
        group_size,
        L,
        (float)scale
    );

    return Out;
}
"""

gqa_cpp = load_inline(
    name="gqa_cpp_opt",
    cpp_sources=cpp_source,
    functions=["gqa_forward"],
    extra_cflags=["-O3"]
)

class ModelNew(nn.Module):
    def __init__(
        self,
        hidden_size: int,
        num_attention_heads: int,
        num_key_value_heads: int,
        head_dim: int,
        max_position_embeddings: int = 4096,
        rope_theta: float = 10000.0,
        attention_dropout: float = 0.0,
    ):
        super().__init__()
        self.hidden_size = hidden_size
        self.num_heads = num_attention_heads
        self.num_kv_heads = num_key_value_heads
        self.head_dim = head_dim
        self.num_key_value_groups = num_attention_heads // num_key_value_heads
        self.attention_dropout = attention_dropout
        self.softmax_scale = head_dim ** (-0.5)

        self.q_proj = nn.Linear(hidden_size, num_attention_heads * head_dim, bias=False)
        self.k_proj = nn.Linear(hidden_size, num_key_value_heads * head_dim, bias=False)
        self.v_proj = nn.Linear(hidden_size, num_key_value_heads * head_dim, bias=False)
        self.o_proj = nn.Linear(num_attention_heads * head_dim, hidden_size, bias=False)

        self.rotary_emb = RotaryEmbedding(
            head_dim,
            max_position_embeddings=max_position_embeddings,
            base=rope_theta,
        )

    def forward(self, hidden_states: torch.Tensor) -> torch.Tensor:
        bsz, q_len, _ = hidden_states.size()

        query_states = self.q_proj(hidden_states)
        key_states = self.k_proj(hidden_states)
        value_states = self.v_proj(hidden_states)

        query_states = query_states.view(bsz, q_len, self.num_heads, self.head_dim).transpose(1, 2)
        key_states = key_states.view(bsz, q_len, self.num_kv_heads, self.head_dim).transpose(1, 2)
        value_states = value_states.view(bsz, q_len, self.num_kv_heads, self.head_dim).transpose(1, 2)

        cos, sin = self.rotary_emb(value_states, seq_len=q_len)
        query_states, key_states = apply_rotary_pos_emb(query_states, key_states, cos, sin)

        attn_output = gqa_cpp.gqa_forward(
            query_states, 
            key_states, 
            value_states, 
            self.softmax_scale
        )

        attn_output = attn_output.transpose(1, 2).contiguous()
        attn_output = attn_output.reshape(bsz, q_len, self.num_heads * self.head_dim)
        attn_output = self.o_proj(attn_output)

        return attn_output

