#include <hip/hip_runtime.h>
#include <hip/hip_fp16.h>
#include <torch/extension.h>

// Fused Scale + Clamp kernel
// Replaces elementwise mul + clamp
// Output is kept in Half precision to be cast to FP8 by PyTorch
// This avoids issues with compiling FP8 types in inline JIT
extern "C" __global__ void fused_scale_clamp_kernel(
    const half* __restrict__ input, 
    half* __restrict__ output, 
    const float* __restrict__ scale_ptr, 
    float min_val,
    float max_val,
    int numel) 
{
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    float scale = *scale_ptr;

    if (idx < numel) {
        float val = __half2float(input[idx]);
        val = val * scale;
        // Clamp 
        val = fmaxf(min_val, fminf(max_val, val));

        output[idx] = __float2half(val);
    }
}

torch::Tensor fused_scale_clamp_hip(torch::Tensor input, torch::Tensor scale, float min_val, float max_val) {
    // Output same shape/dtype as input (Half)
    auto output = torch::empty_like(input);
    int numel = input.numel();
    int block_size = 256;
    int num_blocks = (numel + block_size - 1) / block_size;

    // Ensure contiguous
    if (!input.is_contiguous()) {
        input = input.contiguous();
    }

    fused_scale_clamp_kernel<<<num_blocks, block_size>>>(
        (half*)input.data_ptr<at::Half>(),
        (half*)output.data_ptr<at::Half>(),
        (float*)scale.data_ptr<float>(),
        min_val,
        max_val,
        numel
    );
    return output;
}
"""

