    } else {
        int total = rows * cols;
        const int block_size = 256;
        const int num_blocks = (total + block_size - 1) / block_size;
        silu_mul_kernel_scalar<<<num_blocks, block_size>>>(
            input.data_ptr<float>(),
            output.data_ptr<float>(),
            rows,
            cols
        );
    }

    return output;
}
