# PATCH REFERENCE IMPLEMENTATION BUG
# The reference implementation provided has a dimension mismatch bug in apply_rotary_pos_emb
# when used with the specific transpose options in Model.forward.
# We patch it here to ensure the evaluation can proceed.
try:
    if 'reference' in sys.modules:
        ref_mod = sys.modules['reference']

        def patched_apply_rotary_pos_emb(q, k, cos, sin, position_ids=None, unsqueeze_dim=1):
            # Original bug: cos.unsqueeze(1) creates [seq, 1, dim]
            # q is [bsz, heads, seq, dim] -> dim mismatch between seq and heads (2048 vs 16)
            # Fix: broadcast correctly
            # We want cos [seq, dim] to broadcast to [bsz, heads, seq, dim]
            # Reshape cos/sin to [1, 1, seq, dim]

            # Note: cos shape from RotaryEmbedding is [seq, dim]
            cos = cos.view(1, 1, cos.size(0), cos.size(1))
            sin = sin.view(1, 1, sin.size(0), sin.size(1))

            def rotate_half(x):
                x1 = x[..., : x.shape[-1] // 2]
                x2 = x[..., x.shape[-1] // 2 :]
                return torch.cat((-x2, x1), dim=-1)

            q_embed = (q * cos) + (rotate_half(q) * sin)
            k_embed = (k * cos) + (rotate_half(k) * sin)
            return q_embed, k_embed

        ref_mod.apply_rotary_pos_emb = patched_apply_rotary_pos_emb
        print("[PATCH] Successfully patched reference.apply_rotary_pos_emb")
except Exception as e:
    print(f"[PATCH] Warning: Failed to patch reference: {e}")

