# --- Monkeypatching torch._scaled_mm for Robustness ---
# The reference implementation might fail on some platforms/configurations
# (e.g. HIPBLAS_STATUS_NOT_SUPPORTED). We provide a fallback to standard GEMM.
_orig_scaled_mm = torch._scaled_mm

def _safe_scaled_mm(mat_a, mat_b, scale_a, scale_b, out_dtype=None):
    try:
        return _orig_scaled_mm(mat_a, mat_b, scale_a=scale_a, scale_b=scale_b, out_dtype=out_dtype)
    except RuntimeError as e:
        if "HIPBLAS_STATUS" in str(e):
            # Fallback: Dequantize and GEMM
            # We assume _scaled_mm(A, B) performs A @ B based on dimensions analysis
            a_f = mat_a.float() * scale_a
            b_f = mat_b.float() * scale_b
            res = a_f @ b_f
            return res.to(out_dtype if out_dtype else mat_a.dtype)
        raise e

torch._scaled_mm = _safe_scaled_mm
